body:
Another place where we don't do the right thing with `"1234"` vs `1234`:

```
DELETE /t

PUT /t
{
  "mappings": {
    "t": {
      "properties": {
        "date": {
          "type": "date",
          "format": "YYYYMMddHHmmss"
        }
      }
    }
  }
}

PUT /t/t/1
{
  "date": "20140101000000"
}

PUT /t/t/2
{
  "date": 20140101000000
}

GET /t/_search
{
  "script_fields": {
    "date": {
      "script": "doc['date'].value"
    }
  }
}

GET /t/_search
{
  "query": {
    "match": {
      "date": "20140101000000"
    }
  }
}

GET /t/_search
{
  "query": {
    "match": {
      "date": 20140101000000
    }
  }
}
```
